def get_expected_plan_for_tag(tag: str, language_key: str) -> QueryPlan | None:
    """Maps oracle tags to authoritative structured QueryPlans."""
    if not tag or ":" in tag:
        return None
    lang = LANGUAGE_MAP.get(language_key, "uz-Latn")

    if tag.startswith("lookup_deal_"):
        deal_id = int(tag.split("lookup_deal_")[1])
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="transaction", identifier=deal_id)
        )
    if tag.startswith("lookup_contract_"):
        contract_id = int(tag.split("lookup_contract_")[1])
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="contract", identifier=contract_id)
        )
    if tag.startswith("lookup_stir_"):
        stir = tag.split("lookup_stir_")[1]
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="company", identifier=stir)
        )
    if tag.startswith("lookup_broker_"):
        broker = tag.split("lookup_broker_")[1]
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="broker", identifier=broker)
        )
    if tag == "lookup_fake_deal":
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="transaction", identifier=999999999)
        )
    if tag == "lookup_fake_contract":
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="contract", identifier=999999999)
        )
    if tag == "lookup_fake_stir":
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="company", identifier="999999999")
        )
    if tag == "lookup_fake_broker":
        return QueryPlan(
            kind="lookup", language=lang, lookup=Lookup(entity="broker", identifier="BK999")
        )

    filters = []
    if tag.endswith("_2025"):
        filters.append(
            Filter(field="deal_date", op="between", values=(date(2025, 1, 1), date(2025, 12, 31)))
        )
    elif tag.endswith("_2024"):
        filters.append(
            Filter(field="deal_date", op="between", values=(date(2024, 1, 1), date(2024, 12, 31)))
        )
    elif tag.endswith("_2023"):
        filters.append(
            Filter(field="deal_date", op="between", values=(date(2023, 1, 1), date(2023, 12, 31)))
        )
    elif tag.endswith("_2022"):
        filters.append(
            Filter(field="deal_date", op="between", values=(date(2022, 1, 1), date(2022, 12, 31)))
        )
    elif tag.endswith("_2026"):
        filters.append(
            Filter(field="deal_date", op="between", values=(date(2026, 1, 1), date(2026, 12, 31)))
        )

    if tag in (
        "count_2025",
        "count_2024",
        "count_2023",
        "count_2022",
        "count_2026",
        "all_count",
        "before_2025",
        "before_2024",
        "after_2025",
        "after_2024",
        "through_2025",
    ):
        if tag == "before_2025":
            filters = [Filter(field="deal_date", op="lt", values=(date(2025, 1, 1),))]
        elif tag == "before_2024":
            filters = [Filter(field="deal_date", op="lt", values=(date(2024, 1, 1),))]
        elif tag == "after_2025":
            filters = [Filter(field="deal_date", op="gte", values=(date(2026, 1, 1),))]
        elif tag == "after_2024":
            filters = [Filter(field="deal_date", op="gte", values=(date(2025, 1, 1),))]
        elif tag == "through_2025":
            filters = [Filter(field="deal_date", op="lte", values=(date(2025, 12, 31),))]
        return QueryPlan(
            kind="aggregate", language=lang, metrics=("count",), filters=tuple(filters)
        )

    statuses = {
        "done": ("eq", "Исполнен"),
        "exclude_done": ("ne", "Исполнен"),
        "cancelled": ("eq", "Аннулирован(Не оплачен)"),
        "partial": ("eq", "Исполнен(Частично)"),
    }
    if tag in statuses:
        op, status = statuses[tag]
        return QueryPlan(
            kind="aggregate",
            language=lang,
            metrics=("count",),
            filters=(Filter(field="status", op=op, values=(status,)),),
        )

    if tag == "cancelled_2025":
        filters.append(Filter(field="status", op="eq", values=("Аннулирован(Не оплачен)",)))
        return QueryPlan(
            kind="aggregate", language=lang, metrics=("count",), filters=tuple(filters)
        )
    if tag == "partial_2025":
        filters.append(Filter(field="status", op="eq", values=("Исполнен(Частично)",)))
        return QueryPlan(
            kind="aggregate", language=lang, metrics=("count",), filters=tuple(filters)
        )

    if tag in ("buyer_tonnes_2025", "seller_tonnes_2025"):
        role = "buyer_inn" if tag.startswith("buyer") else "seller_inn"
        filters += [
            Filter(field="tn_ved_code", op="eq", values=("252329",)),
            Filter(field="unit", op="eq", values=("тонна",)),
        ]
        return QueryPlan(
            kind="aggregate",
            language=lang,
            metrics=("sum_volume",),
            filters=tuple(filters),
            group_by=(role,),
            order_by=(Order(field="sum_volume"),),
            limit=1,
        )

    if tag == "min_seller_cement_2025":
        filters = [
            Filter(field="deal_date", op="between", values=(date(2025, 1, 1), date(2025, 12, 31))),
            Filter(field="tn_ved_code", op="eq", values=("252329",)),
            Filter(field="unit", op="eq", values=("тонна",)),
        ]
        return QueryPlan(
            kind="aggregate",
            language=lang,
            metrics=("sum_volume",),
            filters=tuple(filters),
            group_by=("seller_inn",),
            order_by=(Order(field="sum_volume", direction="asc"),),
            limit=1,
        )

    if tag in ("sum_uzs_2025", "sum_usd_2025", "avg_uzs_2025", "min_usd_2025", "max_usd_2025"):
        if "usd" in tag:
            filters.append(Filter(field="currency", op="eq", values=("Доллар США",)))
        metric = "sum_amount"
        if "avg" in tag:
            metric = "avg_amount"
        elif "min" in tag:
            metric = "min_amount"
        elif "max" in tag:
            metric = "max_amount"
        return QueryPlan(
            kind="aggregate",
            language=lang,
            metrics=(metric,),
            money_mode="original" if "usd" in tag else "uzs",
            filters=tuple(filters),
        )

    if tag == "count_usd_deals":
        return QueryPlan(
            kind="aggregate",
            language=lang,
            metrics=("count",),
            filters=(Filter(field="currency", op="eq", values=("Доллар США",)),),
        )

    if tag in ("code_count_2025", "code_fake_count_2025"):
        code = "252329" if tag == "code_count_2025" else "999999"
        filters.append(Filter(field="tn_ved_code", op="eq", values=(code,)))
        return QueryPlan(
            kind="aggregate", language=lang, metrics=("count",), filters=tuple(filters)
        )

    return None
